export function getEnvForTarget(target: InstallTarget, apiKey: string, proxyUrl = getProxyUrl()): Record<string, string> { requireApiKey(apiKey); const baseUrl = proxyUrl.endsWith("/") ? proxyUrl : proxyUrl + "/"; const baseEnv = { DUEL_API_KEY: apiKey, DUEL_PROXY_URL: proxyUrl }; switch (target) { case "claude-code": case "cursor": return { ...baseEnv, ANTHROPIC_API_KEY: \`\${baseUrl}models\` }; case "codex": case "openai-compat": return { ...baseEnv, OPENAI_API_KEY: apiKey, OPENAI_BASE_URL: baseUrl }; case "openclaw": return baseEnv; default: throw new Error(\`Unknown target: \${target}\`); } }

export function buildOpenClawPatch(apiKey: string, proxyUrl = getProxyUrl()): Record<string, unknown> { requireApiKey(apiKey); const baseUrl = proxyUrl.endsWith("/") ? proxyUrl : proxyUrl + "/"; return { agents: { defaults: { provider: "custom", model: { primary: "duel-router", fallback: "gpt-4" } } }, providers: { custom: { type: "openai", env: { base_url: baseUrl, api_key: "\${DUEL_API_KEY}" } } } }; }

export function deepMerge(base: Record<string, unknown>, patch: Record<string, unknown>): Record<string, unknown> { const result = { ...base }; for (const [key, value] of Object.entries(patch)) { if (typeof value === "object" && value !== null && !Array.isArray(value) && typeof result[key] === "object" && result[key] !== null && !Array.isArray(result[key])) { result[key] = deepMerge(result[key] as Record<string, unknown>, value as Record<string, unknown>); } else { result[key] = value; } } return result; }

export async function checkConnectivity(apiKey: string, proxyUrl = getProxyUrl()): Promise<ConnectivityResult> { if (!validateApiKey(apiKey)) return { ok: false, status: "invalid_key", message: "API key is not well-formed" }; const baseUrl = proxyUrl.endsWith("/") ? proxyUrl : proxyUrl + "/"; try { const response = await fetch(\`\${baseUrl}models\`, { headers: { Authorization: \`Bearer \${apiKey}\` } }); if (response.status === 401) return { ok: false, status: "unauthorized", message: "API key is not accepted by the server", httpStatus: 401 }; if (response.status === 200) return { ok: true, status: "ok", message: "Connected successfully", httpStatus: 200 }; return { ok: false, status: "unreachable", message: \`Unexpected status: \${response.status}\`, httpStatus: response.status }; } catch (err) { return { ok: false, status: "unreachable", message: \`Connection failed: \${err instanceof Error ? err.message : String(err)}\` }; } }"
